import { useSyncExternalStore } from "react"
import { LICENSE_CHANGED_EVENT } from "./global-settings-api"

function subscribe(listener: () => void) {
  window.addEventListener(LICENSE_CHANGED_EVENT, listener)
  return () => window.removeEventListener(LICENSE_CHANGED_EVENT, listener)
}

/** License mutations update the same bootstrap snapshot used by Settings. */
export function useLicenseSummary() {
  return useSyncExternalStore(subscribe, () => window.mapsvgReactAdminParams?.license ?? null)
}
