const CHECKOUT_INITIAL_HEIGHT = 1000

const PERIOD_LABELS = {
  daily: { title: "Daily usage", unit: "day", adjective: "daily" },
  weekly: { title: "Weekly usage", unit: "week", adjective: "weekly" },
  monthly: { title: "Monthly usage", unit: "month", adjective: "monthly" },
  annual: { title: "Annual usage", unit: "year", adjective: "annual" },
}

const usagePercent = (used: number, total: number) =>
  Math.min(100, Math.max(0, total > 0 ? (used / total) * 100 : used > 0 ? 100 : 0))
const dateLabel = (date: string) =>
  new Date(date).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  })

export function LiteEnrollmentForm() {
  const id = useId()
  const [email, setEmail] = useState("")
  const [busy, setBusy] = useState(false)
  const [sent, setSent] = useState(false)
  const [error, setError] = useState("")
  const [retryAt, setRetryAt] = useState(0)
  const [now, setNow] = useState(Date.now())
  const remaining = Math.max(0, Math.ceil((retryAt - now) / 1000))
  useEffect(() => {
    if (!retryAt) return
    const timer = window.setInterval(() => setNow(Date.now()), 1000)
    return () => window.clearInterval(timer)
  }, [retryAt])
  return (
    <SettingsSection
      title="Free AI usage for MapSVG Lite"
      help="Get a free AI allowance that resets every week. Verify your email to create a MapSVG Dashboard account and receive your free license key."
    >
      <form
        className="flex flex-col gap-4"
        onSubmit={async (event) => {
          event.preventDefault()
          if (busy || remaining) return
          setBusy(true)
          setError("")
          try {
            const result = await requestLiteLicense(email)
            setSent(true)
            const retryAfter = Math.max(1, Math.min(3600, Number(result.retryAfter) || 60))
            setRetryAt(Date.now() + retryAfter * 1000)
            setNow(Date.now())
          } catch (failure) {
            if (failure instanceof MapSVGApiError && failure.status === 429) {
              const wait = Number(failure.payload?.retryAfter) || 60
              setRetryAt(Date.now() + Math.max(1, Math.min(3600, wait)) * 1000)
              setNow(Date.now())
            }
            setError(
              failure instanceof Error
                ? failure.message
                : "Could not request your license. Please try again.",
            )
          } finally {
            setBusy(false)
          }
        }}
      >
        <SettingsControlField
          id={id}
          label="Email"
          help="We will email a confirmation link. After you confirm, your license key will be available in Dashboard and sent to your email."
        >
          <Input
            id={id}
            type="email"
            required
            maxLength={254}
            autoComplete="email"
            placeholder="you@example.com"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            disabled={busy}
          />
        </SettingsControlField>
        {sent ? (
          <p role="status" className="text-sm text-muted-foreground">
            Check your email for the confirmation link. If a request can be processed for this
            address, we will send you an email.
          </p>
        ) : null}
        {error ? (
          <Alert variant="destructive">
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        ) : null}
        <div>
          <Button type="submit" variant="outline" disabled={busy || remaining > 0}>
            {busy
              ? "Sending…"
              : remaining
                ? `Send again in ${remaining}s`
                : sent
                  ? "Send again"
                  : "Send me a free license key"}
          </Button>
        </div>
      </form>
    </SettingsSection>
  )
}

function DailyUsage({ license }: { license: AiUsageLicense }) {
  return (
    <div>
      <p className="pb-3 text-xs text-muted-foreground">
        Last 3 months · Up to 30 active days · UTC
      </p>
      {!license.dailyUsage.length ? (
        <p className="text-sm text-muted-foreground">No AI activity in the last 3 months.</p>
      ) : (
        <ul className="divide-y" aria-label="Daily AI usage">
          {license.dailyUsage.map((day) => (
            <li key={day.date} className="flex items-center justify-between gap-3 py-3 text-sm">
              <div className="flex items-start gap-3">
                <CalendarDays className="mt-0.5 size-4 text-muted-foreground" aria-hidden />
                <div>
                  <time dateTime={day.date}>{dateLabel(`${day.date}T00:00:00Z`)}</time>
                  <p className="text-xs text-muted-foreground">
                    {day.calls.toLocaleString("en-US")} {day.calls === 1 ? "request" : "requests"}
                  </p>
                </div>
              </div>
              <span className="shrink-0 tabular-nums">{formatAiCredits(day.credits)} credits</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

function SiteUsage({ license }: { license: AiUsageLicense }) {
  return (
    <div>
      {!license.siteUsage.length ? (
        <p className="text-sm text-muted-foreground">No site activity in this period yet.</p>
      ) : (
        <ul className="divide-y" aria-label="AI usage by site">
          {license.siteUsage.map((site) => (
            <li
              key={site.siteUrl ?? "unattributed"}
              className="flex flex-wrap items-center justify-between gap-3 py-3 text-sm"
            >
              <div className="flex min-w-0 flex-1 items-start gap-3">
                <Globe2 className="mt-0.5 size-4 shrink-0 text-muted-foreground" aria-hidden />
                <div className="min-w-0">
                  <p className="break-all">
                    {site.siteUrl?.replace(/^https?:\/\//, "") ?? "Earlier or unattributed usage"}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {site.calls.toLocaleString("en-US")} {site.calls === 1 ? "request" : "requests"}
                  </p>
                  {!site.siteUrl ? (
                    <p className="text-xs text-muted-foreground">
                      This usage was recorded without a site breakdown.
                    </p>
                  ) : null}
                </div>
              </div>
              <div className="shrink-0 text-right tabular-nums">
                <p>{formatAiCredits(site.credits)} credits</p>
                {site.pendingCredits > 0 ? (
                  <p className="text-xs text-muted-foreground">
                    {formatAiCredits(site.pendingCredits)} credits reserved
                  </p>
                ) : null}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

function LicenseUsage({ license, onBuy }: { license: AiUsageLicense; onBuy: () => void }) {
  const [details, setDetails] = useState(false)
  const multipleSites = license.numDomainsMax === 0 || license.numDomainsMax > 1
  const percent = usagePercent(license.used, license.allowance)
  const percentLabel =
    percent > 99 && percent < 100 ? Math.floor(percent * 100) / 100 : Math.round(percent)
  const period = PERIOD_LABELS[license.periodKind]
  const purchased = Math.max(0, license.purchasedRemaining ?? 0)
  const purchasedTotal = Math.max(0, license.purchasedTotal ?? purchased)
  const purchasedUsed = Math.max(0, license.purchasedUsed ?? purchasedTotal - purchased)
  const purchasedPercent = usagePercent(purchasedUsed, purchasedTotal)
  return (
    <>
      <Card role="group" aria-label={period.title} className="shadow-none">
        <CardContent className="space-y-3">
          <div className="flex items-center justify-between gap-3 text-sm">
            <p className="font-medium">{period.title}</p>
            <span className="tabular-nums text-muted-foreground">{percentLabel}% used</span>
          </div>
          <div
            role="progressbar"
            aria-label="Plan usage"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={percent}
            className="h-2 overflow-hidden rounded-full bg-muted"
          >
            <div
              className="h-full bg-primary transition-[width]"
              style={{ width: `${percent}%` }}
            />
          </div>
          <p className="text-sm text-muted-foreground">
            Resets at {dateLabel(license.expiresAt)} (UTC)
          </p>
          {!license.aiAvailable ? (
            <p className="text-sm text-muted-foreground">AI access is inactive for this license.</p>
          ) : null}
        </CardContent>
      </Card>
      <Card role="group" aria-label="Purchased credits" className="shadow-none">
        <CardContent className="space-y-3">
          <div className="flex items-center justify-between gap-3 text-sm">
            <p className="font-medium">Purchased credits</p>
            <span className="tabular-nums text-muted-foreground">
              {formatAiCredits(purchasedUsed)} / {formatAiCredits(purchasedTotal)} used
            </span>
          </div>
          <div
            role="progressbar"
            aria-label="Purchased credits used"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={purchasedPercent}
            aria-valuetext={`${formatAiCredits(purchasedUsed)} of ${formatAiCredits(purchasedTotal)} purchased credits used`}
            className="h-2 overflow-hidden rounded-full bg-muted"
          >
            <div
              className="h-full bg-primary transition-[width]"
              style={{ width: `${purchasedPercent}%` }}
            />
          </div>
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="space-y-1">
              <p className="text-sm text-muted-foreground">No expiry</p>
              <p className="text-xs text-muted-foreground">Used after your plan allowance</p>
            </div>
            <Button type="button" variant="outline" onClick={onBuy}>
              Buy AI credits
            </Button>
          </div>
        </CardContent>
      </Card>
      <Button
        type="button"
        variant="link"
        className="h-auto justify-start gap-1.5 p-0 has-[>svg]:px-0"
        onClick={() => setDetails(!details)}
        aria-expanded={details}
      >
        View usage
        {details ? (
          <ChevronDown className="size-4" aria-hidden />
        ) : (
          <ChevronRight className="size-4" aria-hidden />
        )}
      </Button>
      {details ? (
        <Card role="region" aria-label="AI usage details">
          <CardContent>
            <p className="mb-3 text-xs text-muted-foreground">
              Usage includes credits covered by your plan.
            </p>
            {multipleSites ? (
              <Tabs defaultValue="sites">
                <TabsList className="mb-3 grid grid-cols-2">
                  <TabsTrigger value="sites">Usage by site</TabsTrigger>
                  <TabsTrigger value="daily">Recent usage</TabsTrigger>
                </TabsList>
                <TabsContent value="sites">
                  <SiteUsage license={license} />
                </TabsContent>
                <TabsContent value="daily">
                  <DailyUsage license={license} />
                </TabsContent>
              </Tabs>
            ) : (
              <DailyUsage license={license} />
            )}
          </CardContent>
        </Card>
      ) : null}
    </>
  )
}

export function UsageDialog({
  open,
  onOpenChange,
  initialScreen = "usage",
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  initialScreen?: "usage" | "packs"
}) {
  const params = getAdminParams()
  const summary = useLicenseSummary()
  const bootActivated = Boolean(summary?.hasCode && summary.ok)
  const [activationRequired, setActivationRequired] = useState(false)
  const activated = bootActivated && !activationRequired
  const [licenses, setLicenses] = useState<AiUsageLicense[] | null>(null)
  const [error, setError] = useState("")
  const [loading, setLoading] = useState(false)
  const [screen, setScreen] = useState<"usage" | "packs">("usage")
  const [packs, setPacks] = useState<AiCreditPack[]>([])
  const [purchase, setPurchase] = useState<AiCreditPurchase | null>(null)
  const [buyError, setBuyError] = useState("")
  const [buying, setBuying] = useState(false)
  const [selectedPriceId, setSelectedPriceId] = useState("")
  const [paymentProcessing, setPaymentProcessing] = useState(false)
  const [checkoutLoading, setCheckoutLoading] = useState(false)
  const packId = useId()
  const orders = useRef(new Map<string, { requestId: string; purchase?: AiCreditPurchase }>())
  const [frameHeight, setFrameHeight] = useState(CHECKOUT_INITIAL_HEIGHT)
  const frame = useRef<HTMLIFrameElement>(null)
  const body = useRef<HTMLDivElement>(null)
  const packChoices = useRef<HTMLDivElement>(null)
  const purchaseEpoch = useRef(0)
  const epoch = useRef(0)
  const inFlight = useRef<number | null>(null)
  const refreshAfterPurchase = useRef(false)
  const refresh = useCallback(async (): Promise<void> => {
    if (inFlight.current !== null) return
    const purchaseCompleted = refreshAfterPurchase.current
    const current = ++epoch.current
    inFlight.current = current
    setLoading(true)
    setError("")
    try {
      const data = await getAiUsage()
      if (current === epoch.current) {
        setActivationRequired(false)
        setLicenses(data.licenses)
        window.dispatchEvent(
          new CustomEvent("mapsvg:ai-usage-updated", {
            detail: {
              licenses: data.licenses,
              ...(purchaseCompleted ? { purchaseCompleted: true } : {}),
            },
          }),
        )
        if (purchaseCompleted) refreshAfterPurchase.current = false
      }
    } catch (failure) {
      if (current === epoch.current) {
        setError(failure instanceof Error ? failure.message : "Could not load AI usage.")
        if (failure instanceof MapSVGApiError && failure.payload?.code === "activation_required") {
          setActivationRequired(true)
          setLicenses(null)
          refreshAfterPurchase.current = false
        }
      }
    } finally {
      if (inFlight.current === current) inFlight.current = null
      if (current === epoch.current) setLoading(false)
      // A poll started before settlement cannot acknowledge the purchase. Follow it
      // with a fresh read immediately; a failed post-purchase read retries on the next tick.
      if (current === epoch.current && refreshAfterPurchase.current && !purchaseCompleted)
        void refresh()
    }
  }, [])
  useEffect(() => {
    setLicenses(null)
    setError("")
    setActivationRequired(false)
    setScreen("usage")
    setPurchase(null)
    setPacks([])
    setSelectedPriceId("")
    setBuyError("")
    setBuying(false)
    setPaymentProcessing(false)
    setCheckoutLoading(false)
    orders.current.clear()
    refreshAfterPurchase.current = false
    purchaseEpoch.current++
    if (open && bootActivated) void refresh()
    else setLoading(false)
    return () => {
      epoch.current += 1
      purchaseEpoch.current++
      inFlight.current = null
    }
  }, [open, bootActivated, summary, refresh])
  useEffect(() => {
    if (!open || !activated) return
    const timer = window.setInterval(() => void refresh(), 30_000)
    return () => window.clearInterval(timer)
  }, [open, activated, refresh])
  const goBack = useCallback(
    (purchaseCompleted = false) => {
      if (purchaseCompleted) refreshAfterPurchase.current = true
      purchaseEpoch.current++
      setScreen("usage")
      setPurchase(null)
      setBuyError("")
      setBuying(false)
      setPaymentProcessing(false)
      setCheckoutLoading(false)
      setSelectedPriceId("")
      orders.current.clear()
      void refresh()
    },
    [refresh],
  )
  useEffect(() => {
    if (!open || !purchase) return
    const listener = (event: MessageEvent) => {
      if (
        event.origin !== new URL(purchase.checkoutUrl).origin ||
        event.source !== frame.current?.contentWindow ||
        event.data?.purchaseId !== purchase.purchaseId
      )
        return
      if (event.data?.type === "mapsvg:ai-credit-purchase") {
        if (event.data.status === "fulfilled") goBack(true)
        else if (event.data.status === "processing") setPaymentProcessing(true)
        else if (event.data.status === "ready" || event.data.status === "error") {
          setPaymentProcessing(false)
          setCheckoutLoading(false)
        } else if (event.data.status === "loaded") {
          setCheckoutLoading(false)
          // Paddle may focus its payment field; keep the amount selector visible on arrival.
          packChoices.current
            ?.querySelector<HTMLButtonElement>('[aria-checked="true"]')
            ?.focus({ preventScroll: true })
          if (body.current) body.current.scrollTop = 0
        }
      }
      if (
        event.data?.type === "mapsvg:ai-credit-checkout-height" &&
        Number.isFinite(event.data.height)
      )
        setFrameHeight(Math.max(300, Math.min(1600, event.data.height)))
    }
    window.addEventListener("message", listener)
    return () => window.removeEventListener("message", listener)
  }, [open, purchase, goBack])
  const openPacks = async () => {
    const current = ++purchaseEpoch.current
    setScreen("packs")
    setPurchase(null)
    setSelectedPriceId("")
    setPaymentProcessing(false)
    setCheckoutLoading(false)
    setFrameHeight(CHECKOUT_INITIAL_HEIGHT)
    setBuying(true)
    setBuyError("")
    try {
      const data = await getAiCreditPacks()
      if (current === purchaseEpoch.current) {
        setPacks(data.packs)
        if (data.packs[0]) void buyPack(data.packs[0])
      }
    } catch (failure) {
      if (current === purchaseEpoch.current)
        setBuyError(failure instanceof Error ? failure.message : "Could not load usage packs")
    } finally {
      if (current === purchaseEpoch.current) setBuying(false)
    }
  }
  useEffect(() => {
    if (open && activated && initialScreen === "packs") void openPacks()
  }, [open, activated, initialScreen])
  const buyPack = async (pack: AiCreditPack) => {
    if (paymentProcessing) return
    const current = ++purchaseEpoch.current
    setSelectedPriceId(pack.priceId)
    setPurchase(null)
    setCheckoutLoading(true)
    setFrameHeight(CHECKOUT_INITIAL_HEIGHT)
    setBuying(true)
    setBuyError("")
    let order = orders.current.get(pack.priceId)
    if (!order) {
      order = { requestId: crypto.randomUUID() }
      orders.current.set(pack.priceId, order)
    }
    try {
      const result = order.purchase ?? (await createAiCreditPurchase(pack.priceId, order.requestId))
      if (current === purchaseEpoch.current) {
        order.purchase = result
        setPurchase(result)
        setFrameHeight(CHECKOUT_INITIAL_HEIGHT)
      }
    } catch (failure) {
      if (current === purchaseEpoch.current) {
        setCheckoutLoading(false)
        setBuyError(failure instanceof Error ? failure.message : "Could not start checkout")
      }
    } finally {
      if (current === purchaseEpoch.current) setBuying(false)
    }
  }
  const license = licenses?.[0]
  const checkoutScreen = activated && screen === "packs"
  const preparingCheckout = buying || checkoutLoading
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className={cn(
          "flex max-h-[85vh] flex-col gap-0 overflow-hidden p-0 sm:max-w-2xl",
          checkoutScreen && "h-[85vh]",
        )}
        aria-describedby={undefined}
      >
        <DialogHeader className="shrink-0 border-b border-border px-6 py-5">
          <DialogTitle>{screen === "usage" ? "Usage" : "Checkout"}</DialogTitle>
        </DialogHeader>
        <div
          ref={body}
          data-slot="usage-body"
          className={cn(
            "min-h-0 overflow-y-auto overscroll-contain p-6",
            checkoutScreen && "flex-1",
          )}
          onWheel={(event) => event.stopPropagation()}
          onTouchMove={(event) => event.stopPropagation()}
        >
          {activated && screen === "packs" ? (
            <div className="flex flex-col gap-4">
              <p id={`${packId}-label`} className="text-sm font-medium">
                Amount to add
              </p>
              {packs.length ? (
                <RadioGroup
                  ref={packChoices}
                  aria-labelledby={`${packId}-label`}
                  value={selectedPriceId}
                  disabled={buying || paymentProcessing}
                  onValueChange={(value) => {
                    const pack = packs.find((item) => item.priceId === value)
                    if (pack) void buyPack(pack)
                  }}
                  className="gap-2 rounded-lg border p-2"
                >
                  {packs.map((pack, index) => (
                    <label
                      key={pack.priceId}
                      htmlFor={`${packId}-${index}`}
                      className={`flex cursor-pointer items-center gap-3 rounded-md border p-3 text-sm focus-within:ring-2 focus-within:ring-ring ${selectedPriceId === pack.priceId ? "border-primary ring-1 ring-primary" : "border-transparent"}`}
                    >
                      <RadioGroupItem id={`${packId}-${index}`} value={pack.priceId} />
                      <span className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
                        <span className="font-semibold">
                          {new Intl.NumberFormat("en-US", {
                            style: "currency",
                            currency: pack.currency,
                          }).format(pack.amountMinor / 100)}
                        </span>{" "}
                        <span className="text-muted-foreground">
                          · {formatAiCredits(pack.credits)} credits
                        </span>
                      </span>
                    </label>
                  ))}
                </RadioGroup>
              ) : null}
              {buyError ? (
                <Alert variant="destructive">
                  <AlertDescription>
                    {buyError}
                    <Button
                      type="button"
                      variant="link"
                      disabled={buying}
                      onClick={() => {
                        const pack = packs.find((item) => item.priceId === selectedPriceId)
                        if (pack) void buyPack(pack)
                        else void openPacks()
                      }}
                    >
                      Try again
                    </Button>
                  </AlertDescription>
                </Alert>
              ) : null}
              {preparingCheckout || purchase ? (
                <div
                  className="relative"
                  aria-busy={preparingCheckout}
                  data-slot="checkout-frame"
                  style={{ height: frameHeight }}
                >
                  {purchase ? (
                    <iframe
                      key={purchase.purchaseId}
                      ref={frame}
                      title="AI credits secure checkout"
                      src={purchase.checkoutUrl}
                      allow="payment"
                      referrerPolicy="no-referrer"
                      className="h-full w-full border-0"
                    />
                  ) : null}
                  {preparingCheckout ? (
                    <div className="absolute inset-0 bg-background">
                      <div
                        role="status"
                        aria-live="polite"
                        className="flex h-40 items-center justify-center gap-2 text-sm text-muted-foreground"
                      >
                        <Spinner aria-hidden="true" role="presentation" />
                        <span>
                          {!selectedPriceId
                            ? "Loading credit packs…"
                            : purchase
                              ? "Loading payment form…"
                              : "Preparing checkout…"}
                        </span>
                      </div>
                    </div>
                  ) : null}
                </div>
              ) : null}
              {!buying && !packs.length && !buyError ? (
                <p>Usage packs are currently unavailable.</p>
              ) : null}
            </div>
          ) : !activated ? (
            <div className="flex flex-col gap-6">
              {activationRequired && error ? (
                <Alert variant="destructive">
                  <AlertDescription>{error}</AlertDescription>
                </Alert>
              ) : null}
              <SettingsSection
                title="Activate AI features"
                help="Activate your MapSVG license on this site to access AI features and your included AI usage."
                hideDivider
              >
                <LicenseSettingsPage activationOnly />
              </SettingsSection>
              {isLitePlan(params.licenseProductSlug || params.plan) ? <LiteEnrollmentForm /> : null}
            </div>
          ) : (
            <FieldGroup role="region" aria-label="AI usage" className="gap-6">
              {error ? (
                <Alert variant="destructive">
                  <AlertDescription>
                    <span>{error}</span>
                    <Button type="button" variant="link" onClick={() => void refresh()}>
                      Try again
                    </Button>
                  </AlertDescription>
                </Alert>
              ) : null}
              {!licenses && loading ? (
                <p role="status" className="text-sm text-muted-foreground">
                  Loading AI usage…
                </p>
              ) : null}
              {licenses && !license ? (
                <p className="text-sm text-muted-foreground">
                  No AI usage is available for this site.
                </p>
              ) : null}
              {license ? (
                <LicenseUsage key={license.id} license={license} onBuy={() => void openPacks()} />
              ) : null}
            </FieldGroup>
          )}
        </div>
        <DialogFooter className="shrink-0 border-t border-border px-6 py-4">
          {screen !== "usage" ? (
            <Button type="button" variant="outline" onClick={() => goBack()}>
              <ArrowLeft className="size-4" />
              Go back
            </Button>
          ) : null}
          <Button asChild variant="outline">
            <a
              href={params.dashboardUrl || "https://mapsvg.com/dashboard"}
              target="_blank"
              rel="noreferrer"
            >
              Open MapSVG Dashboard
              <ExternalLink className="size-3.5" />
            </a>
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
